import type { Component } from 'svelte';
import type { RenderOptions } from 'takumi-pdf';

/** Props for Svelte SSR plus the official takumi-pdf 0.11 render options. */
export type RenderTakumiDocumentOptions<Props extends Record<string, any>> = RenderOptions & {
	/** Props passed to the Svelte document template during server rendering. */
	props?: Props;
};

/** The official options accepted by takumi-pdf's binary renderer. */
export type TakumiPdfRenderOptions = RenderOptions;

/**
 * Svelte's SSR output contains hydration boundary comments around dynamic text.
 * They are useful to a hydrating browser, but takumi-pdf treats text separated
 * by those markers as empty. HTML comments have no visual PDF semantics, so
 * remove them before handing the document to the PDF parser.
 */
function stripSvelteSsrMarkers(html: string): string {
	return html.replace(/<!--[\s\S]*?-->/g, '');
}

/**
 * Server-render a Svelte document template to HTML and pass it to takumi-pdf.
 *
 * Both the component body and its SSR head are retained so component-scoped
 * styles continue to apply when Takumi parses the generated HTML.
 */
export async function renderTakumiDocument<Props extends Record<string, any>>(
	template: Component<Props>,
	options: RenderTakumiDocumentOptions<Props> = {}
): Promise<Uint8Array> {
	const { props, ...renderOptions } = options;
	const [{ render: renderSvelte }, { render: renderTakumi }] = await Promise.all([
		import('svelte/server'),
		import('takumi-pdf')
	]);
	const renderComponent = renderSvelte as unknown as (
		component: Component<Props>,
		options: { props?: Props }
	) => { body: string; head: string };
	const { body, head } = await renderComponent(template, { props });
	const pdfBody = stripSvelteSsrMarkers(body);
	const pdfHead = stripSvelteSsrMarkers(head);
	// HTML input otherwise receives Takumi's browser-like 8px body margin,
	// which makes an explicit full-page wrapper overflow onto a blank page.
	const html = `<!doctype html><html><head><style>html,body{margin:0;padding:0}</style>${pdfHead}</head><body>${pdfBody}</body></html>`;

	return renderTakumi(html, renderOptions);
}

/** Short renderer-base-local alias matching Forme's one-call API name. */
export { renderTakumiDocument as renderDocument };

import type { Snippet } from 'svelte';

export type SvgValue = string | number | boolean | null | undefined;
export type SvgStyle = Record<string, SvgValue>;

/** Common static SVG props accepted by pdfcn's shape primitives. */
export interface SvgElementProps {
	children?: Snippet;
	style?: SvgStyle | string;
	class?: string;
	className?: string;
	[attribute: string]: unknown;
}

export interface SvgRootProps extends SvgElementProps {
	width?: string | number;
	height?: string | number;
	viewBox?: string;
}

const SVG_ATTRIBUTE_NAMES: Record<string, string> = {
	className: 'class',
	dominantBaseline: 'dominant-baseline',
	fillOpacity: 'fill-opacity',
	fillRule: 'fill-rule',
	fontFamily: 'font-family',
	fontSize: 'font-size',
	fontStyle: 'font-style',
	fontWeight: 'font-weight',
	letterSpacing: 'letter-spacing',
	markerEnd: 'marker-end',
	markerMid: 'marker-mid',
	markerStart: 'marker-start',
	strokeDasharray: 'stroke-dasharray',
	strokeDashoffset: 'stroke-dashoffset',
	strokeLinecap: 'stroke-linecap',
	strokeLinejoin: 'stroke-linejoin',
	strokeMiterlimit: 'stroke-miterlimit',
	strokeOpacity: 'stroke-opacity',
	strokeWidth: 'stroke-width',
	textAnchor: 'text-anchor'
};

const kebabCase = (property: string): string =>
	property.replace(/[A-Z]/g, (character) => `-${character.toLowerCase()}`);

export const svgStyleToCss = (style?: SvgStyle | string): string | undefined => {
	if (typeof style === 'string') return style;
	if (!style) return undefined;

	return Object.entries(style)
		.filter(([, value]) => value !== undefined && value !== null && value !== '')
		.map(([property, value]) => `${kebabCase(property)}:${String(value)}`)
		.join(';');
};

/** Normalizes React-style SVG attribute aliases for native Svelte SVG nodes. */
export const normalizeTakumiSvgAttributes = (
	props: SvgElementProps
): Record<string, SvgValue> => {
	const normalized: Record<string, SvgValue> = {};

	for (const [name, value] of Object.entries(props)) {
		if (value === undefined || name === 'children') continue;

		if (name === 'style') {
			normalized.style = svgStyleToCss(value as SvgStyle | string);
			continue;
		}

		if (typeof value !== 'function') {
			normalized[SVG_ATTRIBUTE_NAMES[name] ?? name] = value as SvgValue;
		}
	}

	return normalized;
};

export const svgAttributeName = (name: string): string =>
	SVG_ATTRIBUTE_NAMES[name] ?? name;

import { getContext, setContext } from 'svelte';

import { professionalTheme } from '$lib/themes/professional.js';
import type { PdfcnTheme } from '$lib/types/pdf-themes.js';

const PDFCN_THEME_KEY = Symbol('pdfcn-theme');

/**
 * Provides a theme to all pdfcn-svelte components below this point in the
 * component tree. Call once during component initialisation (the
 * `PdfcnThemeProvider` component does this for you).
 */
export function providePdfcnTheme(
	theme: PdfcnTheme = professionalTheme
): PdfcnTheme {
	setContext(PDFCN_THEME_KEY, theme);
	return theme;
}

/**
 * Reads the closest provided theme, falling back to the professional preset.
 */
export function usePdfcnTheme(): PdfcnTheme {
	return getContext<PdfcnTheme | undefined>(PDFCN_THEME_KEY) ?? professionalTheme;
}

